export interface TheoryQuestion {
  id: number;
  question: {
    english: string;
    punjabi: string;
  };
  options: {
    id: string;
    label: string;
    text: {
      english: string;
      punjabi: string;
    };
    correct: boolean;
  }[];
  explanation: {
    english: string;
    punjabi: string;
  };
  section: string;
  totalQuestions: number;
}

function makeAddedPracticeQuestion(
  id: number,
  section: string,
  question: string,
  answers: [string, string, string, string],
  correctIndex: number,
  reasons: [string, string, string, string],
): TheoryQuestion {
  const labels = ['A', 'B', 'C', 'D'];
  const correctAnswer = answers[correctIndex];
  const explanation = `Correct answer: ${correctAnswer}. ${reasons[correctIndex]}\n\nWhy the other answers are incorrect:\n${answers.map((answer, index) => index === correctIndex ? null : `• ${answer}: ${reasons[index]}`).filter(Boolean).join('\n')}`;
  return {
    id,
    section,
    totalQuestions: 150,
    question: {english: question, punjabi: ''},
    options: answers.map((text, index) => ({
      id: labels[index],
      label: labels[index],
      text: {english: text, punjabi: ''},
      correct: index === correctIndex,
    })),
    explanation: {english: explanation, punjabi: ''},
  };
}

function makeMotorwayPracticeQuestion(
  id: number,
  question: string,
  answers: [string, string, string, string],
  correctIndex: number,
  explanation: string,
): TheoryQuestion {
  const labels = ['A', 'B', 'C', 'D'];
  return {
    id,
    section: 'Motorway rules',
    totalQuestions: 150,
    question: {english: question, punjabi: ''},
    options: answers.map((text, index) => ({
      id: labels[index],
      label: labels[index],
      text: {english: text, punjabi: ''},
      correct: index === correctIndex,
    })),
    explanation: {english: explanation, punjabi: ''},
  };
}

